$ErrorActionPreference = 'Stop'
$dir = 'src\editors\website'
if (!(Test-Path (Join-Path $dir 'WebsiteEditor.tsx'))) { throw 'Run from the Onyx Studio root.' }
$patches = @(
  @{ Name = 'WebsiteEditor.tsx'; Hash = 'E8E04AB00CA150B3919A46A667110517A93610A116FB71F192EE87A61E81EC53'; Data = '' }
  @{ Name = 'websiteTypes.ts'; Hash = 'B099C16FA3C986490EAD8DF43BA0E9ECC4F19325AFF747AF00C26C16C74F0D5C'; Data = '' }
  @{ Name = 'websiteExporter.ts'; Hash = '1F52FB8C2636490D8EABFCCB88DE03F7D8890CB4498F26F3048DA2044CD6661D'; Data = '' }
)
foreach ($p in $patches) {
  $path = Join-Path $dir $p.Name
  if (!(Test-Path $path)) { throw "Missing $path" }
  if ((Get-FileHash -Algorithm SHA256 $path).Hash -ne $p.Hash) {
    throw "File changed since upload: $path. No changes made. Upload current files again."
  }
}
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backups = @()
try {
  foreach ($p in $patches) {
    $path = Join-Path $dir $p.Name
    $backup = "$path.$stamp.bak"
    Copy-Item $path $backup
    $backups += @{ Path = $path; Backup = $backup }
    $absolute = (Resolve-Path $path).Path
    [System.IO.File]::WriteAllBytes($absolute, [Convert]::FromBase64String($p.Data))
    Write-Host "Patched $path"
  }
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
  Write-Host 'Divider canvas, inspector and export updated.' -ForegroundColor Green
} catch {
  foreach ($item in $backups) { Copy-Item $item.Backup $item.Path -Force }
  Write-Host 'Restored original files.' -ForegroundColor Yellow
  throw
}
